package app.mindgarden.personal;
import android.content.Context;import android.security.keystore.*;import android.util.Base64;import android.util.AtomicFile;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.KeyStore;import java.util.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import org.json.*;

final class GitHubSync {
 private final Context context;private final File root;private static final String ALIAS="mind-garden-github-v1";
 GitHubSync(Context c){context=c;root=new File(c.getFilesDir(),"github-sync");root.mkdirs();}
 private File connection(){return new File(root,"connection.bin");}
 File safety(String side){return new File(root,"other".equals(side)?"sync-other.zip":"sync-before.zip");}
 private javax.crypto.SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias(ALIAS)){KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());generator.generateKey();}return (javax.crypto.SecretKey)store.getKey(ALIAS,null);}
 private JSONObject config()throws Exception{if(!connection().isFile())return null;try{byte[] bytes=java.nio.file.Files.readAllBytes(connection().toPath());if(bytes.length<13)throw new IOException();Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOf(bytes,12)));return new JSONObject(new String(cipher.doFinal(Arrays.copyOfRange(bytes,12,bytes.length)),StandardCharsets.UTF_8));}catch(Exception e){throw new IOException("同步连接需要重新设置");}}
 private void storeConfig(JSONObject value)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());AtomicFile atomic=new AtomicFile(connection());FileOutputStream out=null;try{out=atomic.startWrite();out.write(cipher.getIV());out.write(cipher.doFinal(value.toString().getBytes(StandardCharsets.UTF_8)));atomic.finishWrite(out);}catch(Exception e){if(out!=null)atomic.failWrite(out);throw e;}}
 JSONObject status()throws Exception{JSONObject c=config(),value=new JSONObject();value.put("configured",c!=null);value.put("owner",c==null?"":c.optString("owner"));value.put("repo",c==null?"":c.optString("repo"));value.put("before",safety("before").isFile());value.put("other",safety("other").isFile());return value;}
 private void identity(JSONObject c)throws Exception{if(!c.optString("owner").matches("[A-Za-z0-9][A-Za-z0-9-]{0,38}")||!c.optString("repo").matches("[A-Za-z0-9_.-]{1,100}")||".".equals(c.optString("repo"))||"..".equals(c.optString("repo"))||c.optString("token").trim().isEmpty())throw new IOException("请填 GitHub 用户名、仓库名和连接密钥");}
 private static class Response{int status;byte[] bytes;Response(int s,byte[] b){status=s;bytes=b;}JSONObject json()throws Exception{return new JSONObject(new String(bytes,StandardCharsets.UTF_8));}}
 private Response request(JSONObject c,String method,String suffix,JSONObject body,boolean raw)throws Exception{identity(c);HttpURLConnection connection=(HttpURLConnection)new URL("https://api.github.com/repos/"+c.getString("owner")+"/"+c.getString("repo")+suffix).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(12000);connection.setReadTimeout(40000);connection.setRequestMethod(method);connection.setRequestProperty("Authorization","Bearer "+c.getString("token"));connection.setRequestProperty("User-Agent","MindGarden-Personal/1.2");connection.setRequestProperty("X-GitHub-Api-Version","2022-11-28");connection.setRequestProperty("Accept",raw?"application/vnd.github.raw+json":"application/vnd.github+json");try{if(body!=null){byte[] bytes=body.toString().getBytes(StandardCharsets.UTF_8);connection.setDoOutput(true);connection.setFixedLengthStreamingMode(bytes.length);connection.setRequestProperty("Content-Type","application/json; charset=UTF-8");try(OutputStream out=connection.getOutputStream()){out.write(bytes);}}int status=connection.getResponseCode();if(status==401)throw new IOException("连接密钥已失效，请重新设置");if(status==403||status==429)throw new IOException("GitHub 暂时限制访问，或密钥没有读写权限，请稍后重试");if(status>=500)throw new IOException("GitHub 暂时不可用，内容已保留在本机");if(status!=200&&status!=201)return new Response(status,new byte[0]);try(InputStream input=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[65536];int n;while((n=input.read(buffer))>0){if(out.size()+n>40*1024*1024)throw new IOException("同步文件过大");out.write(buffer,0,n);}return new Response(status,out.toByteArray());}}catch(SocketTimeoutException e){throw new IOException("连接超时，内容已保留在本机，稍后会重试");}catch(UnknownHostException|ConnectException e){throw new IOException("暂时连不上 GitHub，内容已保留在本机");}finally{connection.disconnect();}}
 private void verify(JSONObject c)throws Exception{Response response=request(c,"GET","",null,false);if(response.status!=200)throw new IOException("没有找到仓库，请检查名称和密钥授权");JSONObject repo=response.json();if(!repo.optBoolean("private",false))throw new IOException("请使用私有仓库，保护你的生活记录");JSONObject permissions=repo.optJSONObject("permissions");if(permissions!=null&&permissions.has("push")&&!permissions.optBoolean("push"))throw new IOException("密钥需要这个仓库的 Contents 读写权限");}
 private void clearStage(File folder){File[] files=folder.listFiles();if(files!=null)for(File file:files){if(file.isDirectory())clearStage(file);file.delete();}folder.delete();}
 private void checkpoint(JSONObject snapshot,String side)throws Exception{if(!(snapshot.opt("goals") instanceof JSONArray)||!(snapshot.opt("ideas") instanceof JSONArray)||!(snapshot.opt("evidence") instanceof JSONArray))throw new IOException("同步副本没有读完整");File stage=new File(root,"stage-"+System.nanoTime());new File(stage,"files").mkdirs();AtomicFile atomic=new AtomicFile(safety(side));FileOutputStream out=null;try{Map<String,JSONObject> attachments=new HashMap<>();JSONArray encoded=snapshot.optJSONArray("attachments");if(encoded!=null)for(int i=0;i<encoded.length();i++){JSONObject a=encoded.getJSONObject(i);String id=a.getString("id");if(!BackupArchive.validId(id)||attachments.put(id,a)!=null)throw new IOException("附件编号无效");}List<String> ids=new ArrayList<>();long total=0;JSONArray ideas=snapshot.getJSONArray("ideas");for(int i=0;i<ideas.length();i++){JSONArray files=ideas.getJSONObject(i).optJSONArray("files");if(files==null)continue;for(int j=0;j<files.length();j++){JSONObject file=files.getJSONObject(j);String id=file.getString("id");JSONObject value=attachments.get(id);if(!BackupArchive.validId(id)||value==null)throw new IOException("同步副本缺少文件");byte[] bytes=Base64.decode(value.getString("data"),Base64.DEFAULT);total+=bytes.length;if(bytes.length>26*1024*1024||total>150*1024*1024||bytes.length!=file.getLong("size"))throw new IOException("附件没有读完整");try(OutputStream target=new FileOutputStream(new File(stage,"files/"+id))){target.write(bytes);}ids.add(id);}}snapshot.remove("attachments");try(OutputStream target=new FileOutputStream(new File(stage,"records.json"))){target.write(snapshot.toString().getBytes(StandardCharsets.UTF_8));}out=atomic.startWrite();BackupArchive.write(stage,ids,new FilterOutputStream(out){@Override public void close()throws IOException{flush();}});atomic.finishWrite(out);out=null;}finally{if(out!=null)atomic.failWrite(out);clearStage(stage);}}
 Object call(JSONObject p)throws Exception{String action=p.optString("action");if("status".equals(action))return status();if("disconnect".equals(action)){new AtomicFile(connection()).delete();return status();}if("safety".equals(action)){checkpoint(p.getJSONObject("snapshot"),p.optString("side"));return true;}
  if("configure".equals(action)){JSONObject old=config(),c=new JSONObject();c.put("owner",p.optString("owner").trim());c.put("repo",p.optString("repo").trim());c.put("token",p.optString("token").trim());if(c.optString("token").isEmpty()&&old!=null&&old.optString("owner").equals(c.optString("owner"))&&old.optString("repo").equals(c.optString("repo")))c.put("token",old.getString("token"));identity(c);verify(c);storeConfig(c);return status();}
  JSONObject c=config();if(c==null)throw new IOException("请先连接 GitHub");if("verify".equals(action)){verify(c);return true;}String key=p.optString("key");boolean state="getState".equals(action)||"putState".equals(action);if(!state&&!key.matches("[a-f0-9]{64}"))throw new IOException("附件编号无效");String suffix="/contents/mind-garden/"+(state?"state.json":"attachments/"+key);JSONObject result=new JSONObject();
  if("getState".equals(action)){Response response=request(c,"GET",suffix,null,false);result.put("status",response.status);if(response.status==404)return result;if(response.status!=200)throw new IOException("云端内容暂时没有读完整");JSONObject value=response.json();String content=value.optString("content");if(content.isEmpty()){Response raw=request(c,"GET",suffix,null,true);if(raw.status!=200||raw.bytes.length>16*1024*1024)throw new IOException("云端内容没有读完整");content=Base64.encodeToString(raw.bytes,Base64.NO_WRAP);}result.put("sha",value.getString("sha"));result.put("content",content);return result;}
  if("getFile".equals(action)){Response response=request(c,"GET",suffix,null,true);result.put("status",response.status);result.put("content",response.status==200?Base64.encodeToString(response.bytes,Base64.NO_WRAP):"");return result;}
  if("putState".equals(action)||"putFile".equals(action)){verify(c);String content=p.optString("content");if(content.length()>30*1024*1024)throw new IOException("同步文件过大");JSONObject body=new JSONObject();body.put("message","Sync Mind Garden");body.put("content",content);String sha=p.optString("sha");if(!sha.isEmpty()){if(!sha.matches("[a-f0-9]{40,64}"))throw new IOException("云端版本无效");body.put("sha",sha);}Response response=request(c,"PUT",suffix,body,false);result.put("status",response.status);if(response.status==409||response.status==422)return result;if(response.status!=200&&response.status!=201)throw new IOException("未能上传，请检查仓库授权");result.put("sha",response.json().getJSONObject("content").getString("sha"));return result;}throw new IOException("没有找到同步操作");
 }
}
